cat > src/gameplay/zones/MagnetZone.ts <<'EOF'
import { BaseZone } from './BaseZone';
import type { Vec3 } from '../../contracts/math';
import type { ZoneBounds } from '../../contracts/zones';

export class MagnetZone extends BaseZone {
  private readonly center: Vec3;

  constructor(
    id: string,
    bounds: ZoneBounds,
    public readonly strength: number = 10.0,
    public readonly isRepelling: boolean = false
  ) {
    super(id, 'magnet', bounds, 0, undefined);
    this.center = {
      x: (bounds.min.x + bounds.max.x) / 2,
      y: (bounds.min.y + bounds.max.y) / 2,
      z: (bounds.min.z + bounds.max.z) / 2
    };
  }

  getForce(position: Vec3, _velocity: Vec3, mass: number): Vec3 {
    const dx = this.center.x - position.x;
    const dy = this.center.y - position.y;
    const dz = this.center.z - position.z;

    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz) || 0.1;
    const clampedDist = Math.max(dist, 0.5);
    const forceMag = (this.strength * mass) / (clampedDist * clampedDist);
    const dir = this.isRepelling ? -1 : 1;

    return {
      x: (dx / dist) * forceMag * dir,
      y: (dy / dist) * forceMag * dir,
      z: (dz / dist) * forceMag * dir
    };
  }
}
